import json, re, time, unicodedata, urllib.request, urllib.parse, sys
D='C:/verger-data/pilot/tk007/'
S=json.load(open(D+'sample60.json',encoding='utf8'))
MIRRORS=['https://overpass-api.de/api/interpreter','https://overpass.kumi.systems/api/interpreter','https://overpass.private.coffee/api/interpreter']
def norm(s):
    s=unicodedata.normalize('NFKD',s.lower());s=''.join(c for c in s if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9 ]','',s).strip()
def q(lat,lng):
    return f'[out:json][timeout:25];(nwr(around:150,{lat},{lng})["name"];nwr(around:150,{lat},{lng})["disused:name"];nwr(around:150,{lat},{lng})["was:name"];);out tags center 200;'
out={}
try: out=json.load(open(D+'osm60.json',encoding='utf8'))
except: pass
for i,p in enumerate(S):
    if p['placeId'] in out: continue
    for attempt in range(6):
        m=MIRRORS[attempt%3]
        try:
            req=urllib.request.Request(m,data=urllib.parse.urlencode({'data':q(p['lat'],p['lng'])}).encode(),headers={'User-Agent':'verger-tk007/1.0'})
            r=json.load(urllib.request.urlopen(req,timeout=40)); break
        except Exception as e:
            r=None; time.sleep(3+attempt*3)
    if r is None: out[p['placeId']]={'err':True}; continue
    n=norm(p['name']); toks=set(n.split())
    hits=[]
    for el in r['elements']:
        t=el['tags']
        for k in ('name','disused:name','was:name'):
            if k in t:
                en=norm(t[k]); et=set(en.split())
                if en==n or n in en or en in n or (len(toks&et)>=max(1,min(len(toks),len(et))-0) and len(toks&et)>=1 and len(toks&et)/max(len(toks),len(et))>=0.5):
                    hits.append({'osm':f"{el['type']}/{el['id']}",'key':k,'name':t[k],'amenity':t.get('amenity'),'lifecycle':{x:t[x] for x in t if x.split(':')[0] in('disused','was','abandoned','razed','demolished') or x in('opening_hours',)},'check_date':t.get('check_date') or t.get('survey:date')})
    out[p['placeId']]={'hits':hits,'n_around':len(r['elements'])}
    json.dump(out,open(D+'osm60.json','w',encoding='utf8'),ensure_ascii=False,indent=1)
    print(i,p['name'],len(hits),flush=True)
    time.sleep(1)
open(D+'OSM60_DONE','w').write('ok')
EOF
