import json, re, time, unicodedata, urllib.request, urllib.parse
D='C:/verger-data/pilot/tk007/'
S=json.load(open(D+'sample60.json',encoding='utf8'))
def norm(s):
    s=unicodedata.normalize('NFKD',s.lower());s=''.join(c for c in s if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9 ]',' ',s).split()
STOP={'the','bar','restaurant','le','la','el','de','di','wine','cocktail','cocktails','and','ristorante','enoteca','club'}
def same(a,b):
    A,B=set(norm(a)),set(norm(b))
    if not A or not B: return False
    ka,kb=A-STOP,B-STOP
    if ka and kb: return len(ka&kb)/min(len(ka),len(kb))>=0.6
    return A==B
out={}
for i,p in enumerate(S):
    la,ln=p['lat'],p['lng']; d=0.004
    url='https://nominatim.openstreetmap.org/search?'+urllib.parse.urlencode({'q':p['name'],'format':'json','limit':5,'extratags':1,'viewbox':f'{ln-d},{la+d},{ln+d},{la-d}','bounded':1})
    r=None
    for a in range(3):
        try:
            r=json.load(urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'verger-tk007/1.0 (research)'}),timeout=25));break
        except Exception as e: time.sleep(3)
    hits=[]
    for x in r or []:
        nm=x.get('name') or x['display_name'].split(',')[0]
        if same(p['name'],nm): hits.append({'osm':f"{x['osm_type']}/{x['osm_id']}",'name':nm,'class':x['class'],'type':x['type'],'website':x.get('extratags',{}).get('website') or x.get('extratags',{}).get('contact:website'),'opening_hours':x.get('extratags',{}).get('opening_hours'),'check_date':x.get('extratags',{}).get('check_date')})
    out[p['placeId']]={'name':p['name'],'err':r is None,'hits':hits}
    print(i,p['name'],'ERR' if r is None else len(hits),[h['class']+'/'+h['type'] for h in hits],flush=True)
    time.sleep(1.1)
json.dump(out,open(D+'nom60.json','w',encoding='utf8'),ensure_ascii=False,indent=1)
EOF
